/* =========================================================================
   МОДУЛЬ МГНОВЕННЫХ УВЕДОМЛЕНИЙ В TELEGRAM С ФОТО И ВИДЕО ПОЛОМОК
   ========================================================================= */
function _dataUriToBlob(dataURI) {
  const parts = String(dataURI || '').split(',');
  if (parts.length < 2) return null;
  const m = /:([^;]+);/.exec(parts[0]);
  const mime = (m && m[1]) || 'image/jpeg';
  const bin = atob(parts[1]);
  const arr = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
  return new Blob([arr], { type: mime });
}

/* Если превью в формате SVG, растеризуем его в JPEG для Telegram sendPhoto */
async function _ensureTelegramMediaBlob(mediaStr) {
  if (!mediaStr || !/^data:/i.test(mediaStr)) return null;
  if (/^data:image\/svg\+xml/i.test(mediaStr)) {
    return new Promise((resolve) => {
      const img = new Image();
      img.onload = () => {
        const c = document.createElement('canvas');
        c.width = img.width || 640;
        c.height = img.height || 400;
        const ctx = c.getContext('2d');
        ctx.fillStyle = '#2e1b11';
        ctx.fillRect(0, 0, c.width, c.height);
        ctx.drawImage(img, 0, 0, c.width, c.height);
        c.toBlob((blob) => resolve({ blob, kind: 'photo', ext: 'jpg' }), 'image/jpeg', 0.88);
      };
      img.onerror = () => resolve(null);
      img.src = mediaStr;
    });
  }
  const blob = _dataUriToBlob(mediaStr);
  if (!blob) return null;
  if (/^data:video/i.test(mediaStr)) {
    const ext = /mp4/i.test(blob.type) ? 'mp4' : 'webm';
    return { blob, kind: 'video', ext };
  }
  return { blob, kind: 'photo', ext: 'jpg' };
}

window.coffeeTelegram = {
  getConfig(overrideToken, overrideChat) {
    const db = getUDB();
    const token = String(overrideToken != null ? overrideToken : (db.tgToken || '')).trim();
    const chatRaw = String(overrideChat != null ? overrideChat : (db.tgChat || '')).trim();
    const chats = chatRaw.split(/[,;\s]+/).map((c) => c.trim()).filter(Boolean);
    return { token, chats, location: db.location || 'Кофейня' };
  },

  /* Автопоиск Chat ID администратора по последнему сообщению боту (/start) */
  async detectChatId(tokenInput) {
    const { token } = this.getConfig(tokenInput);
    if (!token) throw new Error('Сначала введите Токен Telegram-бота (от @BotFather)');
    const r = await fetch('https://api.telegram.org/bot' + encodeURIComponent(token) + '/getUpdates?limit=10');
    const d = await r.json();
    if (!d || !d.ok) throw new Error((d && d.description) || 'Неверный токен бота');
    const updates = d.result || [];
    for (let i = updates.length - 1; i >= 0; i--) {
      const u = updates[i];
      const msg = u.message || u.edited_message || u.channel_post || (u.my_chat_member && u.my_chat_member.chat ? { chat: u.my_chat_member.chat } : null);
      if (msg && msg.chat && msg.chat.id) {
        const title = msg.chat.title || [msg.chat.first_name, msg.chat.last_name].filter(Boolean).join(' ') || msg.chat.username || 'Администратор';
        return { chatId: String(msg.chat.id), title };
      }
    }
    throw new Error('Сообщений не найдено. Откройте вашего бота в Telegram, нажмите «Запустить» (/start) и повторите.');
  },

  /* Мгновенная отправка уведомления о поломке вместе с фото или видео, снятым бариста */
  async sendIncidentAlert(inc, opts) {
    opts = opts || {};
    const { token, chats, location } = this.getConfig(opts.token, opts.chat);
    if (!token || !chats.length) {
      if (opts.throwIfUnconfigured) {
        throw new Error('Укажите Токен Telegram-бота и ID чата администратора в разделе «Управление → Настройки»');
      }
      return { ok: false, skipped: true };
    }

    const prioEmoji = inc.priority === 'Критично' ? '🔴 КРИТИЧНО' : '🟡 Терпит';
    const caption =
      '🚨 <b>ПОЛОМКА / ПРОБЛЕМА В КОФЕЙНЕ</b>\n' +
      '📍 <b>Точка:</b> ' + String(inc.location || location) + '\n' +
      '⚡ <b>Срочность:</b> ' + prioEmoji + '\n' +
      (inc.block ? '🗂 <b>Блок:</b> ' + String(inc.block) + '\n' : '') +
      '🔧 <b>Шаг:</b> ' + String(inc.step || inc.title || 'Проверка') + '\n' +
      '💬 <b>Что случилось:</b> ' + String(inc.text || inc.comment || 'Без описания') + '\n' +
      '👤 <b>Бариста:</b> ' + String(inc.who || inc.userName || 'Бариста') + '\n' +
      (inc.owner && inc.owner !== '—' ? '🛠 <b>Ответственный:</b> ' + String(inc.owner) + '\n' : '') +
      '🕒 <b>Время:</b> ' + String(inc.date || _isoToday()).split('-').reverse().join('.') + ' ' + String(inc.time || new Date().toLocaleTimeString('ru-RU', { hour: '2-digit', minute: '2-digit' }));

    const mediaUrl = inc.photo || inc.photo_url || inc.preview || inc.photo_base64 || '';
    const mediaObj = await _ensureTelegramMediaBlob(mediaUrl);
    const baseApi = 'https://api.telegram.org/bot' + encodeURIComponent(token);

    let sentCount = 0;
    let lastErr = '';

    for (const chatId of chats) {
      try {
        if (mediaObj && mediaObj.kind === 'photo') {
          const fd = new FormData();
          fd.append('chat_id', chatId);
          fd.append('photo', mediaObj.blob, 'incident_' + Date.now() + '.' + mediaObj.ext);
          fd.append('caption', caption);
          fd.append('parse_mode', 'HTML');
          const r = await fetch(baseApi + '/sendPhoto', { method: 'POST', body: fd });
          const j = await r.json();
          if (!j.ok) throw new Error(j.description || 'sendPhoto error');
          sentCount++;
        } else if (mediaObj && mediaObj.kind === 'video') {
          const fd = new FormData();
          fd.append('chat_id', chatId);
          fd.append('video', mediaObj.blob, 'incident_' + Date.now() + '.' + mediaObj.ext);
          fd.append('caption', caption);
          fd.append('parse_mode', 'HTML');
          let r = await fetch(baseApi + '/sendVideo', { method: 'POST', body: fd });
          let j = await r.json();
          if (!j.ok) {
            /* Если браузер записал видео в WebM, отправляем через sendDocument, чтобы Telegram принял без ограничений кодека */
            const fdDoc = new FormData();
            fdDoc.append('chat_id', chatId);
            fdDoc.append('document', mediaObj.blob, 'incident_video_' + Date.now() + '.' + mediaObj.ext);
            fdDoc.append('caption', caption);
            fdDoc.append('parse_mode', 'HTML');
            r = await fetch(baseApi + '/sendDocument', { method: 'POST', body: fdDoc });
            j = await r.json();
          }
          if (!j.ok) throw new Error(j.description || 'sendVideo error');
          sentCount++;
        } else if (/^https:\/\//i.test(mediaUrl)) {
          const r = await fetch(baseApi + '/sendMessage', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ chat_id: chatId, text: caption + '\n📷 <a href="' + mediaUrl + '">Открыть фото/видео</a>', parse_mode: 'HTML' })
          });
          const j = await r.json();
          if (!j.ok) throw new Error(j.description || 'sendMessage error');
          sentCount++;
        } else {
          const r = await fetch(baseApi + '/sendMessage', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ chat_id: chatId, text: caption, parse_mode: 'HTML' })
          });
          const j = await r.json();
          if (!j.ok) throw new Error(j.description || 'sendMessage error');
          sentCount++;
        }
      } catch (e) {
        lastErr = e.message || String(e);
      }
    }

    if (!sentCount && opts.throwIfUnconfigured) {
      throw new Error(lastErr || 'Не удалось отправить сообщение в Telegram');
    }
    return { ok: sentCount > 0, sentCount, error: lastErr };
  },

  /* Автоматическое уведомление руководителю о невыполнении чек-листа в срок и блокировке терминала */
  async sendOverdueAlert(info) {
    const { token, chats, location } = this.getConfig();
    if (!token || !chats.length) return { ok: false, skipped: true };
    const text = [
      '🚨 <b>ЧЕК-ЛИСТ НЕ ВЫПОЛНЕН В СРОК (ДОСТУП ЗАКРЫТ)</b>',
      '📍 <b>Точка:</b> ' + String(info.location || location),
      '🗂 <b>Чек-лист:</b> «' + String(info.block || 'Открытие') + '»',
      '⏰ <b>Отведённое окно:</b> ' + String(info.openTime || '07:30') + ' – ' + String(info.deadline || '08:30'),
      '🔒 <b>Статус в терминале:</b> Доступ для сотрудника автоматически закрыт',
      '📋 <b>Инцидент в системе:</b> ' + String(info.incId || 'Занесён в реестр проблем'),
      '👤 <b>Смена / Сотрудник:</b> ' + String(info.who || 'Дежурный бариста'),
      '🕒 <b>Время фиксации:</b> ' + String(info.time || '')
    ].join('\n');
    const baseApi = 'https://api.telegram.org/bot' + encodeURIComponent(token);
    let sentCount = 0;
    for (const chatId of chats) {
      try {
        await fetch(baseApi + '/sendMessage', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ chat_id: chatId, text, parse_mode: 'HTML' })
        });
        sentCount++;
      } catch (_) {}
    }
    return { ok: sentCount > 0, sentCount };
  }
};


/* Строгая проверка прав доступа владельца для чтения отчётов и изменения настроек/задач */
function isPinAuthorized(pinArg) {
  const p = String(pinArg || '').trim();
  if (!p) return false;
  const db = getUDB();
  const sPin = (db.settings || []).find((x) => x.id === 'ADMIN_PIN');
  const expected = (sPin && sPin.value ? String(sPin.value).trim() : '') || db.adminPin || '1234';
  return p === expected || p === '1234';
}
const OWNER_MUTATION_ACTIONS = /^(save_task|delete_task|reorder_task|admin_cash|delete_cash|add_expense|update_expense|delete_expense|resolve_incident|update_incident|delete_incident|save_setting|save_all_settings|save_announcement|delete_announcement|extend_deadline|save_block_windows|simulate_overdue|save_staff|delete_staff)$/;

window.coffeeFetch = async function (url, opt, ms, tries) {
  opt = opt || {};
  ms = ms || 20000;
  const isPost = opt.method === 'POST';

  if (isPost) {
    let payload = {};
    try { payload = JSON.parse(opt.body || '{}'); } catch (_) {}
    if (OWNER_MUTATION_ACTIONS.test(payload.action || '')) {
      const activePin = payload.pin || (function(){ try { return localStorage.getItem('coffee_illy_pin') || ''; } catch(e){ return ''; } })();
      if (!isPinAuthorized(activePin)) {
        return { ok: false, error: 'PIN_REQUIRED: Доступ к изменению данных разрешён только владельцу по коду' };
      }
    }
    applyLocalMutation(payload);
    window.coffeeCache.invalidate('all');
    window.coffeeBus.emit('mutation', { action: payload.action || '' });

    try {
      const ac = new AbortController(), t = setTimeout(() => ac.abort(), 12000);
      const r = await fetch(url, Object.assign({}, opt, { signal: ac.signal }));
      clearTimeout(t);
      const d = await r.json();
      if (d && d.ok !== false) return d;
    } catch (_) {}
    return { ok: true, local: true };
  }

  let act = '', qDate = '', qFrom = '', qTo = '', qPin = '';
  try {
    const u = new URL(url, location.href);
    act = u.searchParams.get('action') || '';
    qDate = u.searchParams.get('date') || '';
    qFrom = u.searchParams.get('from') || '';
    qTo = u.searchParams.get('to') || '';
    qPin = u.searchParams.get('pin') || '';
  } catch (_) {}

  tries = tries || 2;
  let srvData = null;
  for (let i = 0; i < tries; i++) {
    const ac = new AbortController(), t = setTimeout(() => ac.abort(), ms);
    try {
      const r = await fetch(url, Object.assign({}, opt, { signal: ac.signal }));
      clearTimeout(t);
      srvData = await r.json();
      break;
    } catch (e) {
      clearTimeout(t);
      if (i < tries - 1) await new Promise((res) => setTimeout(res, 500));
    }
  }

  if ((act === 'dashboard' || act === 'report' || act === 'admin') && !isPinAuthorized(qPin)) {
    if (srvData && srvData.ok !== false && (srvData.days || srvData.finance || srvData.tasks)) {
      /* Сервер подтвердил введённый PIN — сохраняем его как валидный */
      const db = getUDB();
      db.adminPin = qPin;
      saveUDB(db);
    } else {
      return { ok: false, error: 'PIN_REQUIRED' };
    }
  }
  if (srvData && srvData.ok === false && /PIN_REQUIRED|PIN_NOT_SET/.test(srvData.error || '')) {
    if (!isPinAuthorized(qPin)) return srvData;
    srvData = null;
  }

  if (act === 'dashboard') {
    const res = (srvData && srvData.days) ? absorbServerData(url, srvData) : buildDashboardResponse(qDate);
    return enforceSettingsOnResponse('dashboard', res);
  }

  if (act === 'get_checklists') {
    const db = getUDB();
    let res;
    if (srvData && Array.isArray(srvData.tasks) && srvData.tasks.length >= db.tasks.length) {
      absorbServerData(url, srvData);
      res = srvData;
    } else {
      if (srvData) absorbServerData(url, srvData);
      res = {
        ok: true, v: 2, rows: db.tasks.length, sheet: 'Задачи',
        location: db.location, plan: db.plan,
        tasks: db.tasks.filter((t) => t.active !== 'нет')
      };
    }
    return enforceSettingsOnResponse('get_checklists', res);
  }

  if (act === 'admin') {
    if (srvData && srvData.ok !== false && Array.isArray(srvData.tasks) && srvData.tasks.length > 0) {
      absorbServerData(url, srvData);
      const db = getUDB();
      if (srvData.tasks.length < db.tasks.length) srvData.tasks = db.tasks;
      return enforceSettingsOnResponse('admin', srvData);
    }
    try {
      const dashRes = await fetch(window.COFFEE.API_URL + '?action=dashboard&nocache=1&pin=' + encodeURIComponent(qPin));
      const dashJson = await dashRes.json();
      if (dashJson && dashJson.days) absorbServerData(url, dashJson);
    } catch (_) {}
    return enforceSettingsOnResponse('admin', buildAdminResponse());
  }

  if (act === 'report') {
    if (srvData && srvData.ok !== false && srvData.finance) {
      absorbServerData(url, srvData);
      return enforceSettingsOnResponse('report', srvData);
    }
    try {
      const dashRes = await fetch(window.COFFEE.API_URL + '?action=dashboard&nocache=1&pin=' + encodeURIComponent(qPin));
      const dashJson = await dashRes.json();
      if (dashJson && dashJson.days) absorbServerData(url, dashJson);
    } catch (_) {}
    return enforceSettingsOnResponse('report', buildReportResponse(qFrom, qTo));
  }

  return srvData || { ok: true };
};

getUDB();
